/* DataForge — Query the Engineer bundle, generated by tools/build.js. */
/* ===== query-engine.js ===== */
/* ============================================================
   Query the Engineer — the answer engine (no DOM).
   A transparent, local portfolio assistant: it matches a question against the
   portfolio's own structured data (src/data/query.js) and composes an answer from
   it. There is no AI model and no network call; nothing typed leaves the browser.
   If nothing in the portfolio matches, it says so instead of guessing.

   Shared by the page (assets/js/query.js), the build (which pre-renders answers to
   the suggested questions for visitors without JavaScript) and the unit tests.

   An answer is { intent, matched, title, blocks, links, follow }:
     blocks  [{ type: 'p', text } | { type: 'list', items: [{ label?, text, href? }] } | { type: 'tags', items }]
     links   [{ text, href, ext? }]  — hrefs come only from the data, never from the question
     follow  suggested next questions
   ============================================================ */
(function (root, factory) {
  var api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else /** @type {any} */ (root).DFQuery = api;
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  /** @typedef {{ label?: string, text: string, href?: string }} Item */
  /** @typedef {{ type: 'p', text: string } | { type: 'list', items: Item[] } | { type: 'tags', items: string[] }} Block */
  /** @typedef {{ text: string, href: string, ext?: boolean }} Link */
  /** @typedef {{ intent: string, matched: boolean, title: string, blocks: Block[], links: Link[], follow: string[] }} Answer */

  /** lower case, straight quotes, accents folded, punctuation as spaces */
  /** @param {string} s */
  var norm = function (s) {
    return ' ' + String(s || '').toLowerCase()
      .replace(/[‘’]/g, "'").replace(/é/g, 'e')
      .replace(/[^a-z0-9+#./&' -]+/g, ' ').replace(/[?!.,;:]+(\s|$)/g, ' ')
      .replace(/\s+/g, ' ').trim() + ' ';
  };
  /** @param {string} s */
  var escRe = function (s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); };
  /** does the normalised question contain this phrase as whole words? */
  /** @param {string} q @param {string} phrase */
  var has = function (q, phrase) { return new RegExp('(^|[^a-z0-9])' + escRe(norm(phrase).trim()) + '(?=$|[^a-z0-9])').test(q); };
  /** @param {string} q @param {string[]} list */
  var any = function (q, list) { for (var i = 0; i < list.length; i++) if (has(q, list[i])) return true; return false; };
  /** @param {string} q @param {string} re */
  var rx = function (q, re) { return new RegExp(re).test(q); };

  /** @param {string} t @returns {Block} */
  var p = function (t) { return { type: 'p', text: t }; };
  /** @param {Item[]} items @returns {Block} */
  var list = function (items) { return { type: 'list', items: items }; };
  /** @param {string[]} items @returns {Block} */
  var tags = function (items) { return { type: 'tags', items: items }; };
  /** @param {string} t @returns {string} */
  var lc = function (t) { return String(t).toLowerCase(); };

  var PROJECT_WORDS = ['project', 'projects', 'built', 'build', 'worked on', 'work on', 'examples', 'case study', 'case studies', 'applications', 'apps', 'portfolio', 'experiments'];
  var CATEGORY_WORDS = {
    data: ['data engineering', 'data pipeline', 'data pipelines', 'pipelines', 'warehouse', 'warehousing', 'etl'],
    ai: ['ai', 'artificial intelligence', 'machine learning', 'ml', 'genai', 'generative ai', 'llm', 'llms', 'agents', 'ai-powered'],
    automation: ['automation', 'automated', 'automate', 'workflow automation'],
    analytics: ['analytics', 'dashboards', 'dashboard', 'reporting', 'visualization', 'visualisation', 'bi'],
    software: ['software', 'web', 'full-stack', 'full stack', 'front-end', 'frontend'],
  };

  /**
   * @param {any} kb the knowledge base (src/data/query.js)
   * @param {string} intent
   * @returns {string[]} three questions to ask next, not the one just answered
   */
  var followFor = function (kb, intent) {
    var map = /** @type {Record<string, number[]>} */ ({
      tata: [3, 4, 6], org: [0, 6, 7], project: [3, 4, 1], category: [4, 2, 0], tech: [1, 5, 3], approach: [3, 1, 6],
      skills: [2, 3, 4], journey: [0, 5, 7], experience: [0, 6, 3], education: [6, 2, 7], about: [6, 3, 7],
      contact: [6, 0, 3], projects: [3, 1, 4], help: [0, 3, 4], fallback: [0, 3, 6],
    });
    return (map[intent] || [0, 3, 6]).map(function (i) { return kb.suggestions[i]; });
  };

  /** @param {any} kb @param {string} slug */
  var project = function (kb, slug) { return kb.projects.filter(function (/** @type {any} */ x) { return x.slug === slug; })[0]; };
  /** @param {any} pr @returns {Item} */
  var projectItem = function (pr) {
    var bits = [pr.kicker + (pr.type === 'Experiment' ? ' (experiment)' : '') + (pr.status ? ' · ' + pr.status : '') + '.', pr.summary];
    return { label: pr.title, text: bits.join(' '), href: pr.url };
  };
  /** @param {any} pr @returns {Link} */
  var projectLink = function (pr) { return { text: pr.type === 'Company project' ? pr.title + ': case study' : pr.title + ': on the homepage', href: pr.url }; };

  /* ---------- answer builders ---------- */
  /** @param {any} kb @param {any} r @returns {Answer} */
  var aboutRole = function (kb, r) {
    var blocks = [p(r.role + ' at ' + r.org + ', ' + r.place + ' · ' + r.when + (r.current ? ' (current role).' : '.')), p(r.description)];
    blocks.push(list(r.achievements.map(function (/** @type {string} */ t) { return { text: t }; })));
    if (r.more && r.more.length) { blocks.push(p('Also:')); blocks.push(list(r.more.map(function (/** @type {string} */ t) { return { text: t }; }))); }
    blocks.push(tags(r.tech));
    var links = r.id === 'tata'
      ? ['knowledge-portal', 'business-sheet', 'resume-matching', 'data-migration'].map(function (s) { return projectLink(project(kb, s)); })
      : [{ text: 'All experience', href: '#experience' }];
    return { intent: r.id === 'tata' ? 'tata' : 'org', matched: true, title: 'Experience · ' + r.org, blocks: blocks, links: links, follow: followFor(kb, r.id === 'tata' ? 'tata' : 'org') };
  };

  /** @param {any} kb @param {any} pr @returns {Answer} */
  var aboutProject = function (kb, pr) {
    var blocks = [p(pr.code + ' · ' + pr.type + ' · ' + pr.kicker + (pr.status ? ' · ' + pr.status : '')), p(pr.summary)];
    /** @type {Item[]} */ var items = [{ label: 'My part', text: pr.contribution || pr.role + '.' }];
    if (pr.approach) items.push({ label: 'How it works', text: pr.approach });
    if (pr.outcome) items.push({ label: 'Result', text: pr.outcome });
    if (pr.type === 'Experiment') items.push({ label: 'Status', text: 'An experiment, shown on the homepage with a sample input and output. Not a live tool.' });
    blocks.push(list(items));
    if (pr.tech) blocks.push(tags(pr.tech));
    else if (pr.type === 'Company project') blocks.push(p('Stack details for this project are not yet published.'));
    return { intent: 'project', matched: true, title: 'Project · ' + pr.title, blocks: blocks, links: [projectLink(pr)], follow: followFor(kb, 'project') };
  };

  /** @param {any} kb @param {string} c @returns {Answer} */
  var aboutCategory = function (kb, c) {
    var label = kb.categories[c];
    var found = kb.projects.filter(function (/** @type {any} */ x) { return x.categories.indexOf(c) !== -1; });
    var domain = kb.domains.filter(function (/** @type {any} */ d) { return d.id === c; })[0];
    var blocks = [p(found.length === 1 ? 'One documented project falls under ' + label + ':' : found.length + ' documented projects fall under ' + label + ':')];
    blocks.push(list(found.map(projectItem)));
    if (domain) blocks.push(p(domain.name + ', as a discipline: ' + domain.line));
    return { intent: 'category', matched: true, title: label + ' projects', blocks: blocks, links: found.filter(function (/** @type {any} */ x) { return x.type === 'Company project'; }).map(projectLink), follow: followFor(kb, 'category') };
  };

  /** every technology named in the data, by lower-case name */
  /** @param {any} kb @returns {Record<string, string>} */
  var techIndex = function (kb) {
    /** @type {Record<string, string>} */ var all = {};
    /** @param {string[]|null} l */
    var add = function (l) { (l || []).forEach(function (t) { if (!all[lc(t)]) all[lc(t)] = t; }); };
    kb.domains.forEach(function (/** @type {any} */ d) { add(d.tech); });
    kb.roles.forEach(function (/** @type {any} */ r) { add(r.tech); });
    kb.projects.forEach(function (/** @type {any} */ x) { add(x.tech); });
    return all;
  };
  /** the technologies a question names: [display name, words to look for in the data].
      The longest phrase wins: "power bi" is Power BI, not "bi"; "sql server" is not "sql". */
  /** @param {any} kb @param {string} q @returns {Array<[string, string[]]>} */
  var techIn = function (kb, q) {
    var idx = techIndex(kb);
    /** @type {Array<{ key: string, phrase: string }>} */ var hits = [];
    Object.keys(idx).forEach(function (key) {
      var names = [key].concat(kb.synonyms[key] || []);
      var best = '';
      names.forEach(function (n) { if (has(q, n) && n.length > best.length) best = n; });
      if (best) hits.push({ key: key, phrase: norm(best).trim() });
    });
    hits.sort(function (a, b) { return b.phrase.length - a.phrase.length; });
    /** @type {Array<[string, string[]]>} */ var out = [];
    /** @type {string[]} */ var taken = [];
    hits.forEach(function (h) {
      // a phrase inside a longer one already matched ("bi" in "power bi") is not its own match
      if (taken.some(function (t) { return t !== h.phrase && has(' ' + t + ' ', h.phrase); })) return;
      if (taken.indexOf(h.phrase) !== -1) return;
      taken.push(h.phrase);
      out.push([idx[h.key], [h.key].concat(kb.synonyms[h.key] || [])]);
    });
    return out;
  };
  /** @param {any} kb @param {[string, string[]]} t @returns {Answer} */
  var aboutTech = function (kb, t) {
    var name = t[0], words = t[1];
    /** @param {string|null|undefined} s */
    var mentions = function (s) { var n = norm(s || ''); return words.some(function (w) { return has(n, w); }); };
    /** @param {string[]|null} l */
    var listed = function (l) { return (l || []).some(function (x) { return words.indexOf(lc(x)) !== -1 || mentions(x); }); };
    /** @type {Item[]} */ var items = [];
    kb.roles.forEach(function (/** @type {any} */ r) {
      var said = r.achievements.concat(r.more || [], [r.description]).filter(mentions);
      if (said.length) items.push({ label: r.org + ' · ' + r.role, text: said.join(' ') });
      else if (listed(r.tech)) items.push({ label: r.org + ' · ' + r.role, text: name + ' is among the technologies of this role.' });
    });
    kb.projects.forEach(function (/** @type {any} */ x) {
      if (listed(x.tech) || mentions(x.summary) || mentions(x.contribution) || mentions(x.approach) || mentions(x.outcome)) {
        items.push({ label: x.title, text: x.summary + (x.status ? ' (' + x.status + ')' : ''), href: x.url });
      }
    });
    kb.education.certs.forEach(function (/** @type {any} */ c) {
      if (mentions(c.title) || mentions(c.issuer)) items.push({ label: 'Certification', text: c.title + ' (' + c.issuer + '): ' + c.note });
    });
    kb.domains.forEach(function (/** @type {any} */ d) {
      if (listed(d.tech)) items.push({ label: 'Discipline · ' + d.name, text: d.line });
    });
    var links = kb.projects.filter(function (/** @type {any} */ x) { return x.type === 'Company project' && items.some(function (i) { return i.href === x.url; }); }).map(projectLink);
    return {
      intent: 'tech', matched: true, title: 'Experience with ' + name,
      blocks: [p('Where ' + name + ' appears in my documented work:'), list(items)],
      links: links, follow: followFor(kb, 'tech'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutApproach = function (kb) {
    return {
      intent: 'approach', matched: true, title: 'How I approach a build',
      blocks: [
        p('I work in five stages, from the business question to a solution people use. ' + kb.workflow.note),
        list(kb.workflow.stages.map(function (/** @type {any} */ s) {
          return { label: s.num + ' ' + s.name, text: s.what + ' Tools: ' + s.tools.join(', ') + '. In practice: ' + s.example[0], href: s.example[1] };
        })),
      ],
      links: [{ text: 'The applications I build: projects', href: '#projects' }],
      follow: followFor(kb, 'approach'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutSkills = function (kb) {
    var tata = kb.roles.filter(function (/** @type {any} */ r) { return r.current; })[0];
    return {
      intent: 'skills', matched: true, title: 'Technologies I work with',
      blocks: [
        p('I work across four engineering disciplines:'),
        list(kb.domains.map(function (/** @type {any} */ d) { return { label: d.name, text: d.tech.join(', ') + '.' }; })),
      ].concat(tata ? [p('In my current role at ' + tata.org + ': ' + tata.tech.join(', ') + '.')] : []),
      links: [{ text: 'Engineering disciplines', href: '#expertise' }],
      follow: followFor(kb, 'skills'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutJourney = function (kb) {
    return {
      intent: 'journey', matched: true, title: 'My professional journey',
      blocks: [
        p('My path runs from software, to data, to AI.'),
        list(kb.chapters.map(function (/** @type {string[]} */ c) { return { label: c[0] + ' · ' + c[1], text: c[2] }; })),
        p(kb.philosophy),
      ],
      links: [{ text: 'Experience', href: '#experience' }, { text: 'About', href: '#about' }],
      follow: followFor(kb, 'journey'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutExperience = function (kb) {
    return {
      intent: 'experience', matched: true, title: 'Experience',
      blocks: [list(kb.roles.map(function (/** @type {any} */ r) { return { label: r.org + ' · ' + r.when, text: r.role + '. ' + r.description }; }))],
      links: [{ text: 'Experience timeline', href: '#experience' }],
      follow: followFor(kb, 'experience'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutEducation = function (kb) {
    var e = kb.education;
    return {
      intent: 'education', matched: true, title: 'Education and certifications',
      blocks: [
        p(e.degree + ', ' + e.school + ' (' + e.when + '). Specialization: ' + e.specialization + '. CGPA ' + e.cgpa + '.'),
        list(e.certs.map(function (/** @type {any} */ c) { return { label: c.title, text: c.issuer + ': ' + c.note }; })),
      ],
      links: [{ text: 'Education', href: '#education' }],
      follow: followFor(kb, 'education'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutMe = function (kb) {
    return {
      intent: 'about', matched: true, title: 'About ' + kb.firstName,
      blocks: [p('I’m ' + kb.name + ', ' + kb.role + ' at ' + kb.company + ' in ' + kb.location + '.'), p(kb.intro), p(kb.philosophy)],
      links: [{ text: 'About', href: '#about' }],
      follow: followFor(kb, 'about'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutContact = function (kb) {
    var c = kb.contact;
    return {
      intent: 'contact', matched: true, title: 'Contact',
      blocks: [
        p('The best way to reach me is email. I’m in ' + kb.location + ', ' + c.timeZone + '.'),
        list([
          { label: 'Email', text: c.email, href: 'mailto:' + c.email },
          { label: 'LinkedIn', text: 'in/gaurang-ashava', href: c.linkedin },
          { label: 'GitHub', text: 'gaurangg123', href: c.github },
          { label: 'Résumé', text: 'View or download it on Google Drive', href: c.resume },
        ]),
      ],
      links: [{ text: 'Contact section', href: '#contact' }],
      follow: followFor(kb, 'contact'),
    };
  };

  /** @param {any} kb @returns {Answer} */
  var aboutProjects = function (kb) {
    return {
      intent: 'projects', matched: true, title: 'Projects',
      blocks: [p('Five enterprise applications from my work at Tata Technologies, and two AI-agent experiments:'), list(kb.projects.map(projectItem))],
      links: [{ text: 'Projects', href: '#projects' }],
      follow: followFor(kb, 'projects'),
    };
  };

  /** @param {any} kb @param {boolean} greeting @returns {Answer} */
  var help = function (kb, greeting) {
    return {
      intent: greeting ? 'help' : 'fallback', matched: greeting,
      title: greeting ? 'What I can answer' : 'Not in this portfolio',
      blocks: greeting
        ? [p('I’m a portfolio assistant. I answer from what this portfolio documents: experience, projects, technologies, education, how I work and how to get in touch.'), p('Pick a question, or type your own.')]
        : [p('I couldn’t match that to anything this portfolio documents, and I won’t guess. Try rephrasing, or one of these:')],
      links: greeting ? [] : [{ text: 'Or email me directly', href: 'mailto:' + kb.contact.email }],
      follow: greeting ? kb.suggestions.slice(0, 4) : followFor(kb, 'fallback').concat([kb.suggestions[7]]),
    };
  };

  /**
   * Answer a question from the portfolio's data.
   * @param {string} question
   * @param {any} kb
   * @returns {Answer}
   */
  function answer(question, kb) {
    var q = norm(question);
    if (!q.trim()) return help(kb, true);

    var askingProjects = any(q, PROJECT_WORDS);

    // contact, and the résumé (unless it is the Resume Matching project)
    var resumeProject = any(q, ['resume matching', 'matching', 'candidate', 'candidates']);
    if (any(q, ['contact', 'email', 'e-mail', 'mail you', 'reach', 'hire', 'get in touch', 'linkedin', 'github', 'connect', 'talk to you']) ||
        (!resumeProject && any(q, ['resume', 'cv']))) return aboutContact(kb);

    // how I work
    if (any(q, ['approach', 'process', 'workflow', 'methodology', 'philosophy', 'way you work', 'how you work', 'steps', 'stages']) ||
        rx(q, ' how (do|would|will) you (build|design|start|plan|work|deliver|tackle|create|develop)')) return aboutApproach(kb);

    // a specific project
    for (var i = 0; i < kb.projects.length; i++) {
      var pr = kb.projects[i];
      if (any(q, [pr.title].concat(pr.aliases))) return aboutProject(kb, pr);
    }
    // an organisation
    for (var j = 0; j < kb.roles.length; j++) {
      if (any(q, [kb.roles[j].org].concat(kb.roles[j].aliases))) return aboutRole(kb, kb.roles[j]);
    }
    // projects in a category
    if (askingProjects) {
      var cats = Object.keys(CATEGORY_WORDS);
      for (var k = 0; k < cats.length; k++) {
        if (any(q, /** @type {any} */ (CATEGORY_WORDS)[cats[k]])) return aboutCategory(kb, cats[k]);
      }
    }
    // a technology
    var tech = techIn(kb, q);
    if (tech.length) return aboutTech(kb, tech[0]);

    if (any(q, ['journey', 'career', 'background', 'path', 'story', 'professional'])) return aboutJourney(kb);
    if (any(q, ['education', 'degree', 'college', 'university', 'study', 'studied', 'cgpa', 'b.tech', 'btech', 'certification', 'certifications', 'certificate', 'certified', 'srm', 'qualification'])) return aboutEducation(kb);
    if (any(q, ['experience', 'worked', 'work history', 'jobs', 'job', 'roles', 'internship', 'internships', 'employer', 'companies'])) return aboutExperience(kb);
    if (any(q, ['technologies', 'technology', 'tech stack', 'stack', 'skills', 'skill', 'tools', 'languages', 'expertise', 'disciplines', 'domains', 'good at', 'specialize', 'specialise'])) return aboutSkills(kb);
    if (askingProjects || any(q, ['work samples', 'what have you made'])) return aboutProjects(kb);
    if (any(q, ['who are you', 'about you', 'yourself', 'introduce', 'who is', 'gaurang', 'what do you do'])) return aboutMe(kb);
    if (any(q, ['hi', 'hello', 'hey', 'help', 'what can you', 'what can i ask', 'start'])) return help(kb, true);
    return help(kb, false);
  }

  return { answer: answer, norm: norm };
});

/* ===== query-ui.js ===== */
/* ---------- Query the Engineer: the conversation ----------
   Suggested questions and typed questions go to the local engine (query-engine.js);
   the answer is built with DOM calls only, so nothing typed is ever parsed as HTML.
   Links come from the portfolio's data, never from the question. ?q= asks on arrival. */
(function () {
  'use strict';
  var root = /** @type {HTMLElement|null} */ (document.querySelector('[data-qe]'));
  var kbEl = document.getElementById('qe-kb');
  var engine = /** @type {any} */ (window).DFQuery;
  if (!root || !kbEl || !engine) return;
  var kb = JSON.parse(kbEl.textContent || '{}');
  var base = root.getAttribute('data-base') || '../';
  var log = /** @type {HTMLElement} */ (root.querySelector('[data-qe-log]'));
  var form = /** @type {HTMLFormElement} */ (root.querySelector('[data-qe-form]'));
  var input = /** @type {HTMLInputElement} */ (root.querySelector('[data-qe-input]'));
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
  var DF = window.DF;
  /** @type {string[]} */ var asked = [];
  /** @type {Array<[string, boolean]>} questions asked while an answer is still arriving */
  var waiting = [];
  var recall = -1, busy = false;

  /** @param {string} tag @param {string} [cls] @param {string} [text] */
  var el = function (tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  };
  /** the arrow icon, from a template on the page so the markup stays in one place */
  var tpl = /** @type {HTMLTemplateElement|null} */ (document.getElementById('qe-arrow'));
  var arrow = tpl && tpl.content.firstElementChild;
  /** @param {string} href @param {string} text @param {string} [cls] */
  var link = function (href, text, cls) {
    var a = /** @type {HTMLAnchorElement} */ (el('a', cls, text));
    var external = /^https?:/.test(href);
    a.href = external || /^mailto:/.test(href) ? href : base + href;
    if (external) {
      a.target = '_blank'; a.rel = 'noopener noreferrer';
      a.appendChild(el('span', 'visually-hidden', ' (opens in a new tab)'));
    }
    if (arrow) a.appendChild(arrow.cloneNode(true));
    return a;
  };

  /** @param {any} a an answer from the engine */
  var renderAnswer = function (a) {
    var art = el('article', 'qe-ans');
    art.appendChild(el('h3', 'qe-ans__title', a.title));
    a.blocks.forEach(function (/** @type {any} */ b) {
      if (b.type === 'p') { art.appendChild(el('p', '', b.text)); return; }
      var ul = el('ul', b.type === 'tags' ? 'tags' : 'qe-ans__list');
      b.items.forEach(function (/** @type {any} */ it) {
        if (b.type === 'tags') { ul.appendChild(el('li', 'tag', it)); return; }
        var li = el('li');
        if (it.label) { li.appendChild(el('b', '', it.label)); li.appendChild(document.createTextNode(' ')); }
        li.appendChild(document.createTextNode(it.text));
        if (it.href) {
          li.appendChild(document.createTextNode(' '));
          var go = link(it.href, /^work\//.test(it.href) ? 'Case study' : /^#/.test(it.href) ? 'On the homepage' : /^mailto:/.test(it.href) ? 'Write' : 'Open', 'qe-ans__go');
          if (it.label) go.insertBefore(el('span', 'visually-hidden', ': ' + it.label), go.lastChild);
          li.appendChild(go);
        }
        ul.appendChild(li);
      });
      art.appendChild(ul);
    });
    if (a.links.length) {
      var links = el('ul', 'qe-ans__links');
      a.links.forEach(function (/** @type {any} */ l) { var li = el('li'); li.appendChild(link(l.href, l.text)); links.appendChild(li); });
      art.appendChild(links);
    }
    if (a.follow.length) {
      var next = el('div', 'qe-ans__next');
      next.appendChild(el('span', 'label', 'Ask next'));
      a.follow.forEach(function (/** @type {string} */ q) {
        var b = /** @type {HTMLButtonElement} */ (el('button', 'qe-chip', q));
        b.type = 'button'; b.setAttribute('data-qe-ask', q);
        next.appendChild(b);
      });
      art.appendChild(next);
    }
    return art;
  };

  /** @param {string} question @param {boolean} [fromInput] */
  var ask = function (question, fromInput) {
    var q = String(question || '').replace(/\s+/g, ' ').trim().slice(0, 200);
    if (!q) return;
    if (busy) { waiting.push([q, !!fromInput]); return; }
    busy = true;
    asked.push(q); recall = -1;
    var mine = el('div', 'qe-msg qe-msg--q');
    mine.appendChild(el('p', '', q));
    log.appendChild(mine);
    var reply = el('div', 'qe-msg qe-msg--a is-typing');
    reply.appendChild(el('span', 'qe-msg__who', 'DF')).setAttribute('aria-hidden', 'true');
    var dots = el('span', 'qe-typing');
    dots.innerHTML = '<i></i><i></i><i></i>';
    dots.appendChild(el('span', 'visually-hidden', 'Looking through the portfolio…'));
    reply.appendChild(dots);
    log.appendChild(reply);
    var smooth = DF && DF.motionOn ? DF.motionOn() : !reduce.matches;
    mine.scrollIntoView({ block: 'nearest', behavior: smooth ? 'smooth' : 'auto' });
    var finish = function () {
      reply.classList.remove('is-typing');
      reply.removeChild(dots);
      reply.appendChild(renderAnswer(engine.answer(q, kb)));
      busy = false;
      mine.scrollIntoView({ block: 'start', behavior: smooth ? 'smooth' : 'auto' });
      if (fromInput) input.focus({ preventScroll: true });
      var next = waiting.shift();
      if (next) ask(next[0], next[1]);
    };
    // a short pause reads as a reply; the answer itself is computed instantly, on this device
    if (smooth) setTimeout(finish, 420); else finish();
  };

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var v = input.value;
    input.value = '';
    ask(v, true);
  });
  input.addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    if (!asked.length) return;
    e.preventDefault();
    if (e.key === 'ArrowUp') recall = recall < 0 ? asked.length - 1 : Math.max(0, recall - 1);
    else recall = recall < 0 ? -1 : recall + 1;
    if (recall >= asked.length) recall = -1;
    input.value = recall < 0 ? '' : asked[recall];
  });
  root.addEventListener('click', function (e) {
    var b = /** @type {Element} */ (e.target).closest('[data-qe-ask]');
    if (b) ask(b.getAttribute('data-qe-ask') || '');
  });
  var clear = root.querySelector('[data-qe-clear]');
  if (clear) clear.addEventListener('click', function () {
    DF.each(log.querySelectorAll('.qe-msg:not([data-qe-welcome])'), function (m) { m.remove(); });
    asked = []; recall = -1; waiting = [];
    input.focus();
  });

  var first = new URLSearchParams(location.search).get('q');
  if (first) ask(first);
})();

/* ===== net-field.js ===== */
/* ---------- a quiet data network behind the Query page ----------
   Drifting nodes that link to their near neighbours, with an occasional packet along
   a link. Colours come from the theme tokens (--lattice-*). It runs at 30 fps only
   while the page is visible, and draws one still frame under reduced motion or
   "Pause motion". Seeded, so every load starts the same. */
(function () {
  'use strict';
  var found = /** @type {HTMLCanvasElement|null} */ (document.querySelector('[data-net]'));
  if (!found || !found.getContext) return;
  var cv = /** @type {HTMLCanvasElement} */ (found);
  var g = /** @type {CanvasRenderingContext2D} */ (cv.getContext('2d'));
  var DF = window.DF;
  var W = 0, H = 0, DPR = 1;
  /** @type {Array<{x:number,y:number,vx:number,vy:number}>} */ var pts = [];
  /** @type {Array<{a:number,b:number,t:number}>} */ var packets = [];
  var A = '56,189,248', B = '139,92,246', E = '148,184,230', light = false;
  var s = 7;
  var rnd = function () { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
  var theme = function () {
    var cs = getComputedStyle(document.documentElement);
    /** @param {string} n @param {string} f */
    var v = function (n, f) { var x = cs.getPropertyValue(n).trim(); return /^\d+,\s*\d+,\s*\d+$/.test(x) ? x.replace(/\s/g, '') : f; };
    A = v('--lattice-a', A); B = v('--lattice-b', B); E = v('--lattice-edge', E);
    light = cs.getPropertyValue('--lattice-blend').trim() === 'source-over';
  };
  var size = function () {
    DPR = Math.min(window.devicePixelRatio || 1, 1.5);
    W = cv.clientWidth; H = cv.clientHeight;
    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
    var n = Math.round(Math.min(70, Math.max(28, (W * H) / 26000)));
    s = 7; pts = [];
    for (var i = 0; i < n; i++) pts.push({ x: rnd() * W, y: rnd() * H, vx: (rnd() - 0.5) * 9, vy: (rnd() - 0.5) * 9 });
    packets = [];
  };
  var LINK = 150;
  var draw = function () {
    g.setTransform(DPR, 0, 0, DPR, 0, 0);
    g.clearRect(0, 0, W, H);
    var k = light ? 0.55 : 1;
    for (var i = 0; i < pts.length; i++) {
      for (var j = i + 1; j < pts.length; j++) {
        var dx = pts[i].x - pts[j].x, dy = pts[i].y - pts[j].y, d = Math.sqrt(dx * dx + dy * dy);
        if (d > LINK) continue;
        g.strokeStyle = 'rgba(' + E + ',' + ((1 - d / LINK) * 0.22 * k).toFixed(3) + ')';
        g.beginPath(); g.moveTo(pts[i].x, pts[i].y); g.lineTo(pts[j].x, pts[j].y); g.stroke();
      }
    }
    for (var m = 0; m < pts.length; m++) {
      g.fillStyle = 'rgba(' + (m % 5 === 0 ? B : A) + ',' + (0.55 * k) + ')';
      g.beginPath(); g.arc(pts[m].x, pts[m].y, m % 5 === 0 ? 2.2 : 1.5, 0, Math.PI * 2); g.fill();
    }
    packets.forEach(function (p) {
      var a = pts[p.a], b = pts[p.b];
      var x = a.x + (b.x - a.x) * p.t, y = a.y + (b.y - a.y) * p.t;
      g.fillStyle = 'rgba(' + A + ',' + (0.9 * k) + ')';
      g.beginPath(); g.arc(x, y, 2.4, 0, Math.PI * 2); g.fill();
    });
  };
  var raf = 0, last = 0, running = false;
  /** @param {number} now */
  var step = function (now) {
    raf = requestAnimationFrame(step);
    if (now - last < 33) return;
    var dt = Math.min(0.1, (now - last) / 1000); last = now;
    pts.forEach(function (p) {
      p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.x < 0 || p.x > W) p.vx = -p.vx;
      if (p.y < 0 || p.y > H) p.vy = -p.vy;
    });
    if (packets.length < 4 && rnd() < 0.04) {
      var a = Math.floor(rnd() * pts.length);
      for (var b = 0; b < pts.length; b++) {
        var dx = pts[a].x - pts[b].x, dy = pts[a].y - pts[b].y;
        if (b !== a && dx * dx + dy * dy < LINK * LINK) { packets.push({ a: a, b: b, t: 0 }); break; }
      }
    }
    packets = packets.filter(function (p) { p.t += dt * 0.7; return p.t < 1; });
    draw();
  };
  var sync = function () {
    if (DF.motionOn() && !document.hidden) { if (!running) { running = true; last = performance.now(); raf = requestAnimationFrame(step); } }
    else { running = false; cancelAnimationFrame(raf); draw(); }
  };
  theme(); size(); draw();
  cv.classList.add('is-ready');
  window.addEventListener('resize', function () { size(); draw(); });
  document.addEventListener('visibilitychange', sync);
  document.addEventListener('df:theme', function () { theme(); draw(); });
  DF.onMotion(sync);
  sync();
})();
